INSERT INTO permissions(code) VALUES ('WORKORDER_INSPECT'),('WORKORDER_INSPECTION_REVIEW'),('WORKORDER_QUALITY_CHECK'),('WORKORDER_DEV_APPROVAL'),('WORKORDER_PHOTO_WRITE');
INSERT INTO role_permissions(role,permission) SELECT r.code,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('BRAND_OWNER','REGIONAL_MANAGER','BRANCH_MANAGER','SERVICE_ADVISOR') AND p.code IN ('WORKORDER_INSPECT','WORKORDER_INSPECTION_REVIEW','WORKORDER_QUALITY_CHECK','WORKORDER_PHOTO_WRITE');
INSERT INTO role_permissions(role,permission) VALUES ('MECHANIC','WORKORDER_INSPECT'),('MECHANIC','WORKORDER_PHOTO_WRITE'),('BRAND_OWNER','WORKORDER_DEV_APPROVAL'),('REGIONAL_MANAGER','WORKORDER_DEV_APPROVAL'),('BRANCH_MANAGER','WORKORDER_DEV_APPROVAL');
CREATE TABLE staff_capabilities(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,quality_review boolean NOT NULL DEFAULT false,safety_review boolean NOT NULL DEFAULT false,attestation varchar(1000) NOT NULL,attested_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,membership_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id),CHECK(NOT safety_review OR quality_review));
CREATE TABLE staff_unavailability(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,membership_id uuid NOT NULL,branch_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason varchar(300) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),CHECK(ends_at>starts_at));
CREATE INDEX staff_time_lookup ON staff_unavailability(tenant_id,branch_id,membership_id,starts_at,ends_at);
